import { initializeApp } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js";
import { getDatabase, ref, get, set, remove, push } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-database.js";
import { getAuth, signInAnonymously } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-auth.js";

const firebaseConfig = {
  apiKey: "AIzaSyDItm8wa73Vc-27G41YFMsoTbpJKE1eqyI",
  authDomain: "dontleak-b54c1.firebaseapp.com",
  databaseURL: "https://dontleak-b54c1-default-rtdb.firebaseio.com",
  projectId: "dontleak-b54c1",
  storageBucket: "dontleak-b54c1.firebasestorage.app",
  messagingSenderId: "87824315321",
  appId: "1:87824315321:web:6e8e145cabfc56a4c3fc68"
};

const app = initializeApp(firebaseConfig);
const db = getDatabase(app);
const auth = getAuth(app);

let uid = "unknown";

signInAnonymously(auth).then((cred)=>{
    uid = cred.user.uid;
});

window.login = async function() {

    const code = document.getElementById("codeInput").value.trim();

    if (!code) {
        alert("Enter an access code");
        return;
    }

    if (code === "OMGSTeven") {
        document.getElementById("adminPanel").style.display = "block";
        loadCodes();
        async function loadLogs(){

    const list = document.getElementById("logList");
    list.innerHTML = "";

    const snap = await get(ref(db,"logs"));

    if(!snap.exists()) return;

    const data = snap.val();

    for(const id in data){

        const item = data[id];

        const li = document.createElement("li");

        li.innerHTML =
            item.time +
            " | " +
            item.code +
            " | UID: " +
            item.uid +
            ` Delete`;

        list.appendChild(li);
    }
}
        return;
    }

    const snap = await get(ref(db, "codes/" + code));

    if (snap.exists()) {
        await push(ref(db, "logs"), {
            code: code,
            uid: uid,
            time: new Date().toLocaleString()
        });

        document.getElementById("terms").style.display = "block";
    } else {
        alert("Invalid code");
    }
};


