window.openArctic = function(){

    const win = window.open("about:blank","_blank");

    win.document.write(`
    (()=>{const r="arctic-root",n=Date.now(),a=atob("").split("|").map(u=>u+"?d="+n),f=document.createElement("iframe");f.allow="fullscreen";f.style.cssText="position:fixed;inset:0;width:100%;height:100%;border:0";document.body.append(f);const g=()=>{const u=a.shift();if(!u){document.body.innerText="Could not load Arctic.";return}fetch(u,{cache:"no-store"}).then(o=>{if(!o.ok)throw 0;return o.text()}).then(h=>{if(!h.includes(r))throw 0;f.srcdoc=h.replace(/
/i,'
