window.addCode = async function(){

    const code = document.getElementById("newCode").value;

    if(!code) return;

    await set(ref(db,"codes/"+code),true);

    loadCodes();
};

async function loadCodes(){

    const list = document.getElementById("codeList");
    list.innerHTML = "";

    const snap = await get(ref(db,"codes"));

    if(!snap.exists()) return;

    const data = snap.val();

    for(const code in data){

        const li = document.createElement("li");

        li.innerHTML = code + ` Delete`;

        list.appendChild(li);
    }
}

window.deleteCode = async function(code){

    await remove(ref(db,"codes/"+code));

    loadCodes();
};

async function loadLogs(){

    const list = document.getElementById("logList");
    list.innerHTML = "";

    const snap = await get(ref(db,"logs"));

    if(!snap.exists()) return;

    const data = snap.val();

    for(const id in data){

        const item = data[id];

        const li = document.createElement("li");

        li.textContent =
            item.time +
            " | " +
            item.code +
            " | UID: " +
            item.uid;

        list.appendChild(li);
    }
}
